CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), login text NOT NULL UNIQUE CHECK (length(login) BETWEEN 3 AND 254), password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roadmaps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '' CHECK(length(description)<=5000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX roadmaps_owner_idx ON roadmaps(owner_id, updated_at DESC);
CREATE TABLE topics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), roadmap_id uuid NOT NULL REFERENCES roadmaps(id) ON DELETE CASCADE, parent_id uuid REFERENCES topics(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 300), description text NOT NULL DEFAULT '' CHECK(length(description)<=20000), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX topics_roadmap_idx ON topics(roadmap_id,parent_id,sort_order,created_at);
CREATE TABLE topic_dependencies (roadmap_id uuid NOT NULL REFERENCES roadmaps(id) ON DELETE CASCADE, predecessor_topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, successor_topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(predecessor_topic_id,successor_topic_id), CHECK(predecessor_topic_id<>successor_topic_id));
CREATE INDEX dependencies_roadmap_idx ON topic_dependencies(roadmap_id);
CREATE TABLE topic_progress (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, completed boolean NOT NULL, completed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,topic_id));
CREATE TABLE topic_notes (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, content text NOT NULL DEFAULT '' CHECK(length(content)<=100000), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,topic_id));
CREATE TABLE topic_layouts (roadmap_id uuid NOT NULL REFERENCES roadmaps(id) ON DELETE CASCADE, topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, x double precision NOT NULL, y double precision NOT NULL, collapsed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(roadmap_id,topic_id));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash bytea NOT NULL UNIQUE, csrf_hash bytea NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE auth_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), token_hash bytea NOT NULL UNIQUE, scopes text[] NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz);
CREATE TABLE idempotency_operations (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, operation_key text NOT NULL CHECK(length(operation_key) BETWEEN 8 AND 200), request_hash bytea NOT NULL, response_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,operation_key));
CREATE TABLE audit_events (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE SET NULL, actor_type text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_user_idx ON audit_events(user_id,created_at DESC);
